requests.sync:
function (doc, oldDoc, meta) {
  // Offline-first action requests. A person's phone may CREATE one, for itself,
  // as 'pending'. Only the backend (admin / import) may advance its status.
  if (doc._deleted) { requireAdmin(); if (oldDoc) { channel("user:" + oldDoc.user_id); } return; }
  if (!doc.user_id) { throw({forbidden: "user_id is required"}); }
  if (oldDoc == null || oldDoc._deleted) {
    requireUser(doc.user_id);
    if (doc.type !== "request") { throw({forbidden: "type must be 'request'"}); }
    if (doc.status !== "pending") { throw({forbidden: "new requests must be 'pending'"}); }
    if (doc._id.indexOf("req::" + doc.user_id + "::") !== 0) { throw({forbidden: "id must be req::<user_id>::<uuid>"}); }
  } else {
    if (oldDoc.user_id !== doc.user_id) { throw({forbidden: "user_id is immutable"}); }
    requireAdmin();
  }
  channel("user:" + doc.user_id);
}
